36	// 아티클 응답 포맷터 (상세/즐겨찾기 — body 포함)
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
39	  const { tags: _tags, ...rest } = article;
40	  return {
41	    ...rest,
42	    tagList: tags,
43	    favorited,
44	    favoritesCount,
45	  };
46	}
47	
48	// 아티클 응답 포맷터 (목록/피드 — body 제외)
49	function formatArticleListResponse(article: any, favorited: boolean, favoritesCount: number) {
50	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
51	  const { body, tags: _tags, ...rest } = article;
52	  return {
53	    ...rest,
54	    tagList: tags,
55	    favorited,
56	    favoritesCount,
57	  };
58	}
