110	app.post("/api/users", async (request: any, reply: any) => {
111	  const { username, email, password } = request.body?.user || {};
112	  if (!username || !email || !password) {
113	    const errs: Record<string, string[]> = {};
114	    if (!username) errs.username = ["can't be blank"];
115	    if (!email) errs.email = ["can't be blank"];
116	    if (!password) errs.password = ["can't be blank"];
117	    reply.code(422).send({ errors: errs });
118	    return;
119	  }
120	  const existing = await prisma.user.findFirst({
121	    where: { OR: [{ username }, { email }] },
122	  });
123	  if (existing) {
124	    const err: Record<string, string[]> = {};
125	    if (existing.username === username) err.username = ["has already been taken"];
126	    if (existing.email === email) err.email = ["has already been taken"];
127	    reply.code(409).send({ errors: err });
128	    return;
129	  }
130	  const hashedPassword = await bcrypt.hash(password, 10);
131	  const user = await prisma.user.create({
132	    data: { username, email, password: hashedPassword },
133	  });
134	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
135	  reply.code(201).send(formatUserResponse(user, token));
136	  return;
137	});
