140	app.post("/api/users/login", async (request: any, reply: any) => {
141	  const { email, password } = request.body?.user || {};
142	  if (!email || !password) {
143	    const errs: Record<string, string[]> = {};
144	    if (!email) errs.email = ["can't be blank"];
145	    if (!password) errs.password = ["can't be blank"];
