167	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
168	  const body = request.body?.user || {};
169	  const updates: any = {};
170	  if (body.username !== undefined) {
171	    if (body.username === "" || body.username === null) {
172	      reply.code(422).send({ errors: { username: ["can't be blank"] } });
173	      return;
174	    }
175	    updates.username = body.username;
176	  }
177	  if (body.email !== undefined) {
178	    if (body.email === "" || body.email === null) {
179	      reply.code(422).send({ errors: { email: ["can't be blank"] } });
180	      return;
181	    }
182	    updates.email = body.email;
183	  }
184	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
185	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
186	  if (body.password !== undefined) {
187	    if (body.password === "" || body.password === null || body.password.length < 8) {
188	      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
189	      return;
190	    }
191	    updates.password = await bcrypt.hash(body.password, 10);
192	  }
193	
194	  // 고유성 검증
195	  if (updates.username || updates.email) {
196	    const existing = await prisma.user.findFirst({
197	      where: {
198	        id: { not: request.userId },
199	        OR: [
200	          updates.username !== undefined ? { username: updates.username } : undefined,
201	          updates.email !== undefined ? { email: updates.email } : undefined,
202	        ].filter((e: any) => e !== undefined),
203	      },
204	    });
205	    if (existing) {
206	      const err: Record<string, string[]> = {};
207	      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
208	      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
209	      reply.code(422).send({ errors: err });
210	      return;
211	    }
212	  }
213	
214	  const user = await prisma.user.update({
215	    where: { id: request.userId },
216	    data: updates,
217	  });
218	  const token = request.headers.authorization.split(" ")[1];
219	  return formatUserResponse(user, token);
220	});
