404	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
405	  });
406	  const articlesCount = await prisma.article.count({ where });
407	  return {
408	    articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
409	    articlesCount,
